var state=runtime.ReadNativeHudState();
var go=new UnityEngine.GameObject("Native HUD candidate acceptance");
var target=new UnityEngine.RenderTexture(1260,542,24,UnityEngine.RenderTextureFormat.ARGB32,UnityEngine.RenderTextureReadWrite.sRGB){name="Native HUD acceptance target"};target.Create();
