view.Bind(state);var initial=view.Root;int stage=0,stable=0,lastFrame=-1;var started=UnityEditor.EditorApplication.timeSinceStartup;double tooltipStarted=0;var width=1260;
var outputDirectory=System.IO.Path.Combine(UnityEngine.Application.dataPath,"../Temp/native-hud",System.DateTime.UtcNow.ToString("yyyyMMdd-HHmmss-fff"));System.IO.Directory.CreateDirectory(outputDirectory);
var results=new System.Collections.Generic.List<object>();
