void Require(bool ok,string reason){checks++;if(!ok)throw new System.Exception(reason);}
UnityEngine.UIElements.VisualElement Q(string name)=>UnityEngine.UIElements.UQueryExtensions.Q<UnityEngine.UIElements.VisualElement>(view.Root,name);
void Capture(string name){var previous=UnityEngine.RenderTexture.active;var pixels=new UnityEngine.Texture2D(target.width,target.height,UnityEngine.TextureFormat.RGBA32,false,false);try{UnityEngine.RenderTexture.active=target;pixels.ReadPixels(new UnityEngine.Rect(0,0,target.width,target.height),0,0);pixels.Apply();
 UnityEngine.Color At(float x,float y)=>pixels.GetPixel(UnityEngine.Mathf.Clamp((int)(x*settings.scale),0,target.width-1),UnityEngine.Mathf.Clamp(target.height-1-(int)(y*settings.scale),0,target.height-1));
 var radar=Q("native-hud-radar").worldBound;var player=At(radar.center.x,radar.center.y);Require(player.r+player.g+player.b>2,"Radar player not painted");var corner=At(radar.x+8,radar.y+8);Require(corner.r+corner.g+corner.b<1.5,"Radar white placeholder");
 var border=Q("hud-right").worldBound;Require(At(border.center.x,border.y+.25f).b>.12,"Clipping removed HUD border");
 var hp=Q("hud-hp-bar-fill").worldBound;var health=At(hp.x+hp.width*.25f,hp.center.y);Require(health.r>.4&&health.r>health.g*1.5,"HP gradient missing/white");
 System.IO.File.WriteAllBytes(System.IO.Path.Combine(outputDirectory,name+".png"),UnityEngine.ImageConversion.EncodeToPNG(pixels));}finally{UnityEngine.RenderTexture.active=previous;UnityEngine.Object.Destroy(pixels);}}
