void Pointer(UnityEngine.UIElements.VisualElement element,UnityEngine.Vector2 at,bool down){var raw=new UnityEngine.Event {type=down?UnityEngine.EventType.MouseDown:UnityEngine.EventType.MouseUp,button=0,mousePosition=at};if(down){using(var evt=UnityEngine.UIElements.PointerDownEvent.GetPooled(raw)){evt.target=element;element.SendEvent(evt);}}else using(var evt=UnityEngine.UIElements.PointerUpEvent.GetPooled(raw)){evt.target=element;element.SendEvent(evt);}}
tick=()=>{
 try{
  if(!UnityEditor.EditorApplication.isPlaying||UnityEditor.EditorApplication.timeSinceStartup-started>180)throw new System.Exception("Play ended/deadline");
  if(lastFrame==UnityEngine.Time.frameCount)return;lastFrame=UnityEngine.Time.frameCount;view.Prepare(settings.scale);
