  if(stage==0){var images=new System.Collections.Generic.List<object>();foreach(var image in UnityEngine.UIElements.UQueryExtensions.Query<UnityEngine.UIElements.Image>(view.Root).ToList())if(image.image is UnityEngine.RenderTexture texture){var old=UnityEngine.RenderTexture.active;var read=new UnityEngine.Texture2D(texture.width,texture.height,UnityEngine.TextureFormat.RGBA32,false,false);try{UnityEngine.RenderTexture.active=texture;read.ReadPixels(new UnityEngine.Rect(0,0,texture.width,texture.height),0,0);read.Apply();var center=read.GetPixel(texture.width/2,texture.height/2);var path=System.IO.Path.Combine(UnityEngine.Application.dataPath,"../Temp/native-hud/raw-"+image.parent.name+".png");System.IO.File.WriteAllBytes(path,UnityEngine.ImageConversion.EncodeToPNG(read));images.Add(new{host=image.parent.name,w=texture.width,h=texture.height,uv=image.uv.ToString(),bounds=image.worldBound.ToString(),center=center.ToString()});}finally{UnityEngine.RenderTexture.active=old;UnityEngine.Object.Destroy(read);}}System.IO.File.WriteAllText(System.IO.Path.Combine(UnityEngine.Application.dataPath,"../Temp/native-hud/images.json"),Newtonsoft.Json.JsonConvert.SerializeObject(images,Newtonsoft.Json.Formatting.Indented));}
  if(stage==0){state.Dominant=new EchoSphere.Presentation.NativeHudView.Formation {Id="line",Name="ЛИНИЯ"};state.Secondary=new EchoSphere.Presentation.NativeHudView.Formation {Id="triangle",Name="ТРЕУГОЛЬНИК"};state.XpPercent=45;state.HpPercent=64;state.Hp="64/100";state.Resonance="100/100";state.ResonancePercent=100;state.ResonanceReady=true;state.Pois=new[]{new EchoSphere.Presentation.NativeHudRadarView.Poi(state.PlayerX-1300,state.PlayerY,true,"boss_trace"),new EchoSphere.Presentation.NativeHudRadarView.Poi(state.PlayerX,state.PlayerY+500,true,"cache"),new EchoSphere.Presentation.NativeHudRadarView.Poi(state.PlayerX+1000,state.PlayerY+1000,true,"rupture")};view.Bind(state);}
  else if(stage==1){
   var first=Q("hud-formation-0");var second=Q("hud-formation-1");Pointer(first,first.worldBound.center,true);Require(Q("hud-network-tooltip").style.display.value==UnityEngine.UIElements.DisplayStyle.Flex,"Hold tooltip missing");Pointer(first,second.worldBound.center,false);expectedActions++;Require(actions==expectedActions,"Pointer drag did not swap slots");Require(Q("hud-network-tooltip").style.display.value==UnityEngine.UIElements.DisplayStyle.None,"Successful swap did not hide tooltip");
   Pointer(first,first.worldBound.center,true);using(var cancel=UnityEngine.UIElements.PointerCancelEvent.GetPooled()){cancel.target=first;first.SendEvent(cancel);}Pointer(first,second.worldBound.center,false);Require(actions==expectedActions,"Cancelled drag swapped slots");
   Pointer(first,first.worldBound.center,true);allowSwap=false;Pointer(first,second.worldBound.center,false);expectedActions++;Require(actions==expectedActions,"Rejected swap callback missing");Require(Q("hud-network-tooltip").style.display.value==UnityEngine.UIElements.DisplayStyle.Flex,"Rejected swap hid tooltip");allowSwap=true;view.HideTooltip();
