 }catch(System.Exception e){results.Add(new{failedStage=stage,width,parent=parent.contentRect.ToString(),left=Q("hud-left").worldBound.ToString(),right=Q("hud-right").worldBound.ToString(),target=target.width+"x"+target.height,scale=settings.scale});Finish("FAIL "+e);}
};UnityEditor.EditorApplication.update+=tick;return "Started native HUD candidate in independent target";


